 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Find matching, contiguous colored runs on opposite borders.
    runs = []
    for side in ('left', 'right', 'top', 'bottom'):
        n = h if side in ('left', 'right') else w
        vals = [grid[i][0] if side == 'left' else
                grid[i][w-1] if side == 'right' else
                grid[0][i] if side == 'top' else grid[h-1][i]
                for i in range(n)]
        i = 0
        while i < n:
            color = vals[i]
            j = i + 1
            while j < n and vals[j] == color:
                j += 1
            if color != bg and j - i >= 2:
                runs.append((side, color, i, j))
            i = j

    pair = None
    for a in runs:
        for b in runs:
            if a[0] == 'left' and b[0] == 'right' and a[1] == b[1] and a[3]-a[2] == b[3]-b[2]:
                pair = (a, b, 'vertical')
                break
            if a[0] == 'top' and b[0] == 'bottom' and a[1] == b[1] and a[3]-a[2] == b[3]-b[2]:
                pair = (a, b, 'horizontal')
                break
        if pair:
            break
    if pair is None:
        return out

    first, second, orientation = pair
    border_color = first[1]
    segments = {first[0]: first, second[0]: second}
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and grid[r][c] != border_color]

    for r, c, color in markers:
        if orientation == 'vertical':
            pos = r
            # Identify which border segment this marker is aligned with.
            src = None
            for side, seg in segments.items():
                if seg[2] <= pos < seg[3]:
                    src = seg
                    break
            if src is None:
                continue
            index = pos - src[2]
            other = second if src is first else first
            mapped_r = other[2] + index
            # Ray from the marker to its associated border; counterpart row is fully filled.
            if src[0] == 'left':
                for cc in range(1, c):
                    out[r][cc] = color
            else:
                for cc in range(c + 1, w - 1):
                    out[r][cc] = color
            out[r][c] = 4
            for cc in range(1, w - 1):
                out[mapped_r][cc] = color
        else:
            pos = c
            src = None
            for side, seg in segments.items():
                if seg[2] <= pos < seg[3]:
                    src = seg
                    break
            if src is None:
                continue
            index = pos - src[2]
            other = second if src is first else first
            mapped_c = other[2] + index
            if src[0] == 'top':
                for rr in range(1, r):
                    out[rr][c] = color
            else:
                for rr in range(r + 1, h - 1):
                    out[rr][c] = color
            out[r][c] = 4
            for rr in range(1, h - 1):
                out[rr][mapped_c] = color
    return out


if __name__ == '__main__':
    pass
